// Builds the request inspector (app/) into one self-contained HTML page and
// writes it to src/app-html.ts, which both MCP servers serve as an MCP App
// resource. Run after changing anything in app/; a test fails when the
// generated file is stale. The output depends only on the sources and the
// installed esbuild, so the same sources always give the same page.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const appDir = join(here, "../app");
const out = join(here, "../src/app-html.ts");

// esbuild comes with tsup, this package's bundler.
const require = createRequire(import.meta.url);
const esbuild = createRequire(require.resolve("tsup"))("esbuild");

/** The inspector as one HTML document. */
export async function buildInspectorHtml() {
  const script = await esbuild.build({
    entryPoints: [join(appDir, "inspector.ts")],
    bundle: true,
    write: false,
    minify: true,
    format: "iife",
    target: "es2020",
    legalComments: "none",
    charset: "utf8",
    tsconfig: join(appDir, "tsconfig.json"),
    logLevel: "silent",
  });
  const js = script.outputFiles[0].text.trim();
  const css = (
    await esbuild.transform(readFileSync(join(appDir, "inspector.css"), "utf8"), {
      loader: "css",
      minify: true,
      charset: "utf8",
      legalComments: "none",
    })
  ).code.trim();
  if (/<\/(script|style)/i.test(js + css)) {
    throw new Error("The inspector's code contains a closing script or style tag");
  }
  const template = readFileSync(join(appDir, "inspector.html"), "utf8");
  // Whitespace between tags goes before the code goes in, so the code is kept as built.
  const html = template
    .replace(/>\s+</g, "><")
    .replace(/\s*\/\* INSPECTOR_CSS \*\/\s*/, () => css)
    .replace(/\s*\/\* INSPECTOR_JS \*\/\s*/, () => js)
    .trim();
  if (html.includes("INSPECTOR_CSS") || html.includes("INSPECTOR_JS")) {
    throw new Error("app/inspector.html lost a placeholder");
  }
  return html;
}

/** The generated module's exports for `html`. */
export function inspectorExports(html) {
  return { html, hash: createHash("sha256").update(html).digest("hex").slice(0, 12) };
}

async function main() {
  const { html, hash } = inspectorExports(await buildInspectorHtml());
  const source = [
    "// Generated by scripts/build-app.mjs from app/. Do not edit.",
    "",
    "/** The request inspector, one self-contained HTML page (app.ts). */",
    `export const INSPECTOR_HTML = ${JSON.stringify(html)};`,
    "",
    "/** The first 12 hex digits of the page's SHA-256, which name its resource. */",
    `export const INSPECTOR_HASH = ${JSON.stringify(hash)};`,
    "",
  ].join("\n");
  // Written as the repository's Prettier would write it, so formatting
  // the tree never changes the generated file.
  const prettier = await import("prettier");
  const options = (await prettier.resolveConfig(out)) ?? {};
  writeFileSync(out, await prettier.format(source, { ...options, filepath: out }));
  console.log(`built the inspector: ${Buffer.byteLength(html)} bytes, ${hash}`);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  await main();
}
